#define MAX_N 100
#define MAX_V 2000
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point p1, p2;
} Segment;

Point buildings[MAX_N][MAX_N];
int n_vertices[MAX_N];
int n_buildings;
Point S, T;
double sun_vector_x, sun_vector_y;

// graph for shortest path
double dist[MAX_V][MAX_V];
int V; // number of vertices in graph

Point shadow_points[MAX_V];
int shadow_count;

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double point_dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy);
}

int on_segment(Point p, Segment seg) {
    double cp = cross(seg.p1, seg.p2, p);
    if (fabs(cp) > EPS) return 0;
    double dp = dot(seg.p1, seg.p2, p);
    if (dp < -EPS) return 0;
    double len2 = (seg.p2.x - seg.p1.x)*(seg.p2.x - seg.p1.x) + (seg.p2.y - seg.p1.y)*(seg.p2.y - seg.p1.y);
    if (dp > len2 + EPS) return 0;
    return 1;
}

int segments_intersect(Segment a, Segment b, Point *p) {
    double d1 = cross(b.p1, b.p2, a.p1);
    double d2 = cross(b.p1, b.p2, a.p2);
    double d3 = cross(a.p1, a.p2, b.p1);
    double d4 = cross(a.p1, a.p2, b.p2);
    if (((d1 > EPS && d2 < -EPS) || (d1 < -EPS && d2 > EPS)) &&
        ((d3 > EPS && d4 < -EPS) || (d3 < -EPS && d4 > EPS))) {
        double t = d1 / (d1 - d2);
        p->x = a.p1.x + t * (a.p2.x - a.p1.x);
        p->y = a.p1.y + t * (a.p2.y - a.p1.y);
        return 1;
    }
    if (fabs(d1) < EPS && on_segment(a.p1, b)) { *p = a.p1; return 1; }
    if (fabs(d2) < EPS && on_segment(a.p2, b)) { *p = a.p2; return 1; }
    if (fabs(d3) < EPS && on_segment(b.p1, a)) { *p = b.p1; return 1; }
    if (fabs(d4) < EPS && on_segment(b.p2, a)) { *p = b.p2; return 1; }
    return 0;
}

int point_in_convex_polygon(Point p, Point poly[], int n) {
    int pos = 0, neg = 0;
    for (int i = 0; i < n; i++) {
        double c = cross(poly[i], poly[(i+1)%n], p);
        if (c > EPS) pos = 1;
        if (c < -EPS) neg = 1;
    }
    return !(pos && neg);
}

// check if segment is in shadow (sun blocked by any building)
int in_shadow(Point a, Point b) {
    // Check if the line from a to b is entirely along building edges (shaded)
    // We'll consider the segment as shaded if it lies on building perimeters
    // Actually we need to check if any point on segment is in shadow from sun
    // For simplicity, we check if the segment is inside any building's shadow
    // The shadow of a building extends infinitely in the direction opposite to sun
    // A point is in shadow if a ray from the point towards the sun hits a building before infinite

    // We'll check if any building blocks the sun for points on the segment
    // A point is in sunlight if there is no building between it and the sun
    // Since sun is at infinity, we consider direction (-sun_vector_x, -sun_vector_y)

    // Check if the entire segment is inside a building (should not happen as we cannot walk inside)
    // Check if segment lies on building boundary (shaded)
    for (int bld = 0; bld < n_buildings; bld++) {
        int n = n_vertices[bld];
        Point *poly = buildings[bld];
        // Check if segment is collinear with any edge and within that edge
        for (int i = 0; i < n; i++) {
            Point p1 = poly[i];
            Point p2 = poly[(i+1)%n];
            Segment edge = {p1, p2};
            // Check if a and b both lie on this edge
            if (on_segment(a, edge) && on_segment(b, edge)) {
                return 1; // walking on building perimeter is shaded
            }
        }
        // Also check if segment is inside the polygon (should not happen)
    }

    // For sunlight check: if any point on segment is in sunlight, it's not fully shaded
    // We'll sample points along the segment and check shadow
    int samples = 10;
    for (int k = 0; k <= samples; k++) {
        double t = (double)k / samples;
        Point p;
        p.x = a.x + t * (b.x - a.x);
        p.y = a.y + t * (b.y - a.y);

        // Check if p is in shadow: cast ray towards sun direction
        // Ray: p + u * (sun_vector_x, sun_vector_y), u > 0
        // Check intersection with any building edge
        int blocked = 0;
        Segment ray;
        ray.p1 = p;
        ray.p2.x = p.x + sun_vector_x * 1000000.0;
        ray.p2.y = p.y + sun_vector_y * 1000000.0;

        for (int bld = 0; bld < n_buildings; bld++) {
            int n = n_vertices[bld];
            Point *poly = buildings[bld];
            for (int i = 0; i < n; i++) {
                Point p1 = poly[i];
                Point p2 = poly[(i+1)%n];
                Segment edge = {p1, p2};
                Point inter;
                if (segments_intersect(ray, edge, &inter)) {
                    // Check if intersection is in front of p (u > 0)
                    double dx = inter.x - p.x;
                    double dy = inter.y - p.y;
                    if (dx*sun_vector_x + dy*sun_vector_y > EPS) {
                        blocked = 1;
                        break;
                    }
                }
            }
            if (blocked) break;
        }
        if (!blocked) {
            return 0; // found a point in sunlight
        }
    }
    return 1; // all sample points are in shadow
}

