        }
        dist[i][i] = 0;
    }

    // Add edges if direct walk is possible (not through building interior) and compute sunlight distance
    for (int i = 0; i < V; i++) {
        for (int j = i+1; j < V; j++) {
            Point a = shadow_points[i];
            Point b = shadow_points[j];

            // Check if segment intersects any building interior
            int blocked = 0;
            for (int bld = 0; bld < n_buildings; bld++) {
                int n = n_vertices[bld];
                Point *poly = buildings[bld];
                // Check if midpoint is inside polygon (since endpoints are on vertices)
                Point mid;
                mid.x = (a.x + b.x) / 2;
                mid.y = (a.y + b.y) / 2;
                if (point_in_convex_polygon(mid, poly, n)) {
