                    break;
                }
                // Check if segment crosses any edge
                for (int k = 0; k < n; k++) {
                    Point p1 = poly[k];
                    Point p2 = poly[(k+1)%n];
                    Segment edge = {p1, p2};
                    Segment seg = {a, b};
                    Point inter;
                    if (segments_intersect(seg, edge, &inter)) {
                        // If intersection is not at endpoints
                        if (point_dist(inter, a) > EPS && point_dist(inter, b) > EPS) {
                            blocked = 1;
                            break;
                        }
                    }
                }
                if (blocked) break;
            }
            if (blocked) continue;

            double d = point_dist(a, b);
            if (in_shadow(a, b)) {
                // Fully shaded, no sunlight distance
                dist[i][j] = dist[j][i] = 0;
            } else {
                // Sunlight distance is the full distance (since we cannot avoid sun on this path)
                dist[i][j] = dist[j][i] = d;
            }
        }
    }

    // Floyd-Warshall for shortest sunlight path
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
