#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define INF 1e100
#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

typedef struct {
    int a, b;
    double w;
} Edge;

static double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
static double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
static Point sub(Point a, Point b) { Point r = {a.x - b.x, a.y - b.y}; return r; }
static Point addp(Point a, Point b) { Point r = {a.x + b.x, a.y + b.y}; return r; }
static Point mul(Point a, double t) { Point r = {a.x * t, a.y * t}; return r; }
static double norm(Point a) { return sqrt(dot(a, a)); }
static double dist(Point a, Point b) { return norm(sub(a, b)); }

static int dcmp(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

static int on_segment(Point a, Point b, Point p) {
    if (fabs(cross(sub(b, a), sub(p, a))) > EPS) return 0;
    return dcmp(dot(sub(p, a), sub(p, b))) <= 0;
}

static int seg_proper_intersect(Point a, Point b, Point c, Point d) {
    double c1 = cross(sub(b, a), sub(c, a));
    double c2 = cross(sub(b, a), sub(d, a));
    double c3 = cross(sub(d, c), sub(a, c));
    double c4 = cross(sub(d, c), sub(b, c));
    return dcmp(c1) * dcmp(c2) < 0 && dcmp(c3) * dcmp(c4) < 0;
}

static int segments_intersect(Point a, Point b, Point c, Point d) {
    if (seg_proper_intersect(a, b, c, d)) return 1;
    if (on_segment(a, b, c)) return 1;
    if (on_segment(a, b, d)) return 1;
    if (on_segment(c, d, a)) return 1;
    if (on_segment(c, d, b)) return 1;
    return 0;
}

static int point_in_convex_or_boundary(Point *poly, int m, Point p) {
    int sign = 0;
    for (int i = 0; i < m; i++) {
        Point a = poly[i], b = poly[(i + 1) % m];
        double cr = cross(sub(b, a), sub(p, a));
        int s = dcmp(cr);
        if (s == 0) {
            if (on_segment(a, b, p)) return 1;
            continue;
        }
        if (sign == 0) sign = s;
        else if (sign != s) return 0;
    }
    return 1;
}

static int segment_inside_polygon_open(Point *poly, int m, Point p, Point q) {
    Point mid = mul(addp(p, q), 0.5);
    return point_in_convex_or_boundary(poly, m, mid);
}

static int visible_without_entering(Point p, Point q, Point *allPts, int totalPts,
                                    Point **polys, int *psz, int npoly) {
    (void)allPts; (void)totalPts;
    for (int i = 0; i < npoly; i++) {
        Point *poly = polys[i];
        int m = psz[i];

        for (int j = 0; j < m; j++) {
            Point a = poly[j], b = poly[(j + 1) % m];
            if (seg_proper_intersect(p, q, a, b)) return 0;
        }

        int cntTouch = 0;
        for (int j = 0; j < m; j++) {
            Point a = poly[j], b = poly[(j + 1) % m];
            if (on_segment(a, b, p) || on_segment(a, b, q)) continue;
            if (segments_intersect(p, q, a, b)) cntTouch++;
        }
        if (cntTouch >= 2) {
            if (segment_inside_polygon_open(poly, m, p, q)) return 0;
        } else {
            if (segment_inside_polygon_open(poly, m, p, q)) {
                int pOn = 0, qOn = 0;
                for (int j = 0; j < m; j++) {
                    Point a = poly[j], b = poly[(j + 1) % m];
                    if (on_segment(a, b, p)) pOn = 1;
                    if (on_segment(a, b, q)) qOn = 1;
                }
                if (!(pOn && qOn)) return 0;
            }
        }
    }
    return 1;
}

static double sunlight_cost(Point p, Point q, Point sunDir,
                            Point **polys, int *psz, int npoly) {
    double L = dist(p, q);
    if (L < EPS) return 0.0;

    Point d = sub(q, p);
    double len = norm(d);
    d = mul(d, 1.0 / len);

    double *ts = (double *)malloc(sizeof(double) * (4 * npoly + 10));
    int tn = 0;
    ts[tn++] = 0.0;
    ts[tn++] = 1.0;

    for (int i = 0; i < npoly; i++) {
        Point *poly = polys[i];
        int m = psz[i];
        for (int j = 0; j < m; j++) {
            Point a = poly[j], b = poly[(j + 1) % m];
            Point e = sub(b, a);
            double den = cross(d, e);
            if (fabs(den) < EPS) continue;
            double t = cross(sub(a, p), e) / den;
            double u = cross(sub(a, p), d) / den;
            if (t > EPS && t < 1.0 - EPS && u > EPS && u < 1.0 - EPS) {
                ts[tn++] = t;
            }
        }
    }

    for (int i = 0; i < tn; i++) {
        for (int j = i + 1; j < tn; j++) {
            if (ts[j] < ts[i]) {
                double tmp = ts[i];
                ts[i] = ts[j];
                ts[j] = tmp;
            }
        }
    }

    int un = 0;
    for (int i = 0; i < tn; i++) {
        if (un == 0 || fabs(ts[i] - ts[un - 1]) > 1e-8) ts[un++] = ts[i];
    }

    double shaded = 0.0;
    for (int i = 0; i + 1 < un; i++) {
        double l = ts[i], r = ts[i + 1];
        if (r - l < 1e-10) continue;
        double midt = (l + r) * 0.5;
        Point mid = addp(p, mul(sub(q, p), midt));

        int inShadow = 0;
        for (int k = 0; k < npoly && !inShadow; k++) {
            Point *poly = polys[k];
            int m = psz[k];
            for (int j = 0; j < m; j++) {
                Point a = poly[j], b = poly[(j + 1) % m];
                if (on_segment(a, b, mid)) {
                    inShadow = 1;
                    break;
                }
            }
            if (inShadow) break;

            Point farp = addp(mid, mul(sunDir, 1e7));
            for (int j = 0; j < m; j++) {
                Point a = poly[j], b = poly[(j + 1) % m];
                if (segments_intersect(mid, farp, a, b)) {
                    if (!(on_segment(a, b, mid))) {
                        inShadow = 1;
                        break;
                    }
                }
            }
        }

        if (inShadow) shaded += (r - l) * L;
    }

    free(ts);
    return L - shaded;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point S, T, sun;
    scanf("%lf %lf %lf %lf %lf %lf", &S.x, &S.y, &T.x, &T.y, &sun.x, &sun.y);

    Point **polys = (Point **)malloc(sizeof(Point *) * n);
    int *psz = (int *)malloc(sizeof(int) * n);

    int totalPts = 2;
    for (int i = 0; i < n; i++) {
        scanf("%d", &psz[i]);
        polys[i] = (Point *)malloc(sizeof(Point) * psz[i]);
        for (int j = 0; j < psz[i]; j++) {
            scanf("%lf %lf", &polys[i][j].x, &polys[i][j].y);
        }
        totalPts += psz[i];
    }

    Point *nodes = (Point *)malloc(sizeof(Point) * totalPts);
    int idx = 0;
    nodes[idx++] = S;
    nodes[idx++] = T;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < psz[i]; j++) nodes[idx++] = polys[i][j];
    }

    sun = mul(sun, -1.0);

    double **g = (double **)malloc(sizeof(double *) * totalPts);
    for (int i = 0; i < totalPts; i++) {
        g[i] = (double *)malloc(sizeof(double) * totalPts);
        for (int j = 0; j < totalPts; j++) g[i][j] = (i == j ? 0.0 : INF);
    }

    int base = 2;
    for (int i = 0; i < n; i++) {
        int m = psz[i];
        for (int j = 0; j < m; j++) {
            int u = base + j;
            int v = base + (j + 1) % m;
            g[u][v] = g[v][u] = 0.0;
        }
        base += m;
    }

    for (int i = 0; i < totalPts; i++) {
        for (int j = i + 1; j < totalPts; j++) {
            if (g[i][j] == 0.0) continue;
            if (!visible_without_entering(nodes[i], nodes[j], nodes, totalPts, polys, psz, n)) continue;
            double c = sunlight_cost(nodes[i], nodes[j], sun, polys, psz, n);
            if (c < g[i][j]) g[i][j] = g[j][i] = c;
        }
    }

    double *dista = (double *)malloc(sizeof(double) * totalPts);
    int *used = (int *)calloc(totalPts, sizeof(int));
    for (int i = 0; i < totalPts; i++) dista[i] = INF;
    dista[0] = 0.0;

    for (int it = 0; it < totalPts; it++) {
        int v = -1;
        for (int i = 0; i < totalPts; i++) {
            if (!used[i] && (v == -1 || dista[i] < dista[v])) v = i;
        }
        if (v == -1 || dista[v] >= INF / 2) break;
        used[v] = 1;
        for (int u = 0; u < totalPts; u++) {
            if (dista[u] > dista[v] + g[v][u]) {
                dista[u] = dista[v] + g[v][u];
            }
        }
    }

    printf("%.10f\n", dista[1]);

    for (int i = 0; i < n; i++) free(polys[i]);
    free(polys);
    free(psz);
    free(nodes);
    for (int i = 0; i < totalPts; i++) free(g[i]);
    free(g);
    free(dista);
    free(used);

    return 0;
}

import sys
import math

EPS = 1e-10
INF = 1e100

def sgn(x):
    if x > EPS:
        return 1
    if x < -EPS:
        return -1
    return 0

class Pt:
    __slots__ = ("x", "y")
    def __init__(self, x=0.0, y=0.0):
        self.x = float(x)
        self.y = float(y)
    def __add__(self, other):
        return Pt(self.x + other.x, self.y + other.y)
    def __sub__(self, other):
        return Pt(self.x - other.x, self.y - other.y)
    def __mul__(self, k):
        return Pt(self.x * k, self.y * k)
    def __truediv__(self, k):
        return Pt(self.x / k, self.y / k)

def dot(a, b):
    return a.x * b.x + a.y * b.y

def cross(a, b):
    return a.x * b.y - a.y * b.x

def norm(a):
    return math.hypot(a.x, a.y)

def dist(a, b):
    return norm(a - b)

def point_on_segment(p, a, b):
    return sgn(cross(b - a, p - a)) == 0 and sgn(dot(p - a, p - b)) <= 0

def seg_proper_intersect(a, b, c, d):
    c1 = sgn(cross(b - a, c - a))
    c2 = sgn(cross(b - a, d - a))
    c3 = sgn(cross(d - c, a - c))
    c4 = sgn(cross(d - c, b - c))
    if c1 == 0 and point_on_segment(c, a, b): return True
    if c2 == 0 and point_on_segment(d, a, b): return True
    if c3 == 0 and point_on_segment(a, c, d): return True
    if c4 == 0 and point_on_segment(b, c, d): return True
    return c1 * c2 < 0 and c3 * c4 < 0

def line_intersection_param(a, b, c, d):
    # a + t*(b-a) intersects c + u*(d-c)
    r = b - a
    s = d - c
    den = cross(r, s)
    if abs(den) < EPS:
        return None
    t = cross(c - a, s) / den
    u = cross(c - a, r) / den
    return t, u

def point_in_convex(poly, p):
    # boundary counts as inside/blocked
    n = len(poly)
    prev = 0
    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]
        cr = sgn(cross(b - a, p - a))
        if cr == 0 and point_on_segment(p, a, b):
            return True
        if cr != 0:
            if prev != 0 and cr != prev:
                return False
            prev = cr
    return True

def segment_blocked_by_polygon(a, b, poly):
    # Open segment intersects or lies inside polygon interior/boundary
    if point_in_convex(poly, a) or point_in_convex(poly, b):
        return True
    n = len(poly)
    for i in range(n):
        c = poly[i]
        d = poly[(i + 1) % n]
        if seg_proper_intersect(a, b, c, d):
            return True
    return False

def segment_inside_any_building(a, b, polys):
    for poly in polys:
        if segment_blocked_by_polygon(a, b, poly):
            return True
    return False

def sunlight_cost(a, b, polys, sun):
    # cost = length of parts of segment [a,b] exposed to sunlight
    ab = b - a
    L = norm(ab)
    if L < EPS:
        return 0.0

    events = [0.0, 1.0]

    # perimeter walking is shaded: split at all intersections with polygon edges
    for poly in polys:
        n = len(poly)
        for i in range(n):
            c = poly[i]
            d = poly[(i + 1) % n]
            res = line_intersection_param(a, b, c, d)
            if res is None:
                # collinear overlap with edge => add edge endpoints projections if on segment
                if sgn(cross(b - a, c - a)) == 0 and sgn(cross(b - a, d - a)) == 0:
                    denom = dot(ab, ab)
                    if denom > EPS:
                        tc = dot(c - a, ab) / denom
                        td = dot(d - a, ab) / denom
                        if -EPS <= tc <= 1 + EPS:
                            events.append(min(1.0, max(0.0, tc)))
                        if -EPS <= td <= 1 + EPS:
                            events.append(min(1.0, max(0.0, td)))
                continue
            t, u = res
            if -EPS <= t <= 1 + EPS and -EPS <= u <= 1 + EPS:
                events.append(min(1.0, max(0.0, t)))

    # shadow boundaries from all vertices, ray in opposite sun direction
    dirv = Pt(-sun.x, -sun.y)
    far = 10**9
    for poly in polys:
        for v in poly:
            res = line_intersection_param(a, b, v, v + dirv)
            if res is None:
                continue
            t, u = res
            if -EPS <= t <= 1 + EPS and u >= -EPS:
                events.append(min(1.0, max(0.0, t)))

    events = sorted(events)
    uniq = []
    for x in events:
        if not uniq or abs(x - uniq[-1]) > 1e-9:
            uniq.append(x)
    events = uniq

    sunny = 0.0
    for i in range(len(events) - 1):
        l = events[i]
        r = events[i + 1]
        if r - l < 1e-10:
            continue
        m = (l + r) * 0.5
        p = a + ab * m

        shaded = False

        # on perimeter => shaded
        for poly in polys:
            n = len(poly)
            hit_edge = False
            for j in range(n):
                if point_on_segment(p, poly[j], poly[(j + 1) % n]):
                    hit_edge = True
                    break
            if hit_edge:
                shaded = True
                break
        if shaded:
            continue

        # in shadow if ray toward sun hits a building
        q = p
        ray_end = q + sun * far
        for poly in polys:
            if point_in_convex(poly, q):
                shaded = True
                break
            n = len(poly)
            found = False
            for j in range(n):
                c = poly[j]
                d = poly[(j + 1) % n]
                res = line_intersection_param(q, ray_end, c, d)
                if res is None:
                    continue
                t, u = res
                if t > EPS and -EPS <= u <= 1 + EPS:
                    found = True
                    break
            if found:
                shaded = True
                break

        if not shaded:
            sunny += (r - l) * L

    return sunny

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)

    # Assumed input format:
    # n
    # sx sy tx ty
    # sunx suny
    # for each polygon:
    #   m x1 y1 x2 y2 ... xm ym
    n = int(next(it))
    S = Pt(float(next(it)), float(next(it)))
    T = Pt(float(next(it)), float(next(it)))
    sun = Pt(float(next(it)), float(next(it)))

    polys = []
    for _ in range(n):
        m = int(next(it))
        poly = []
        for _ in range(m):
            x = float(next(it)); y = float(next(it))
            poly.append(Pt(x, y))
        polys.append(poly)

    # Candidate graph vertices: S, T, all polygon vertices
    pts = [S, T]
    owner = [(-1, -1), (-1, -1)]  # (polygon index, vertex index) or (-1,-1)
    for pi, poly in enumerate(polys):
        for vi, p in enumerate(poly):
            pts.append(p)
            owner.append((pi, vi))

    N = len(pts)
    g = [[] for _ in range(N)]

    # Add perimeter edges with zero sunlight cost
    idx = 2
    poly_start = []
    for pi, poly in enumerate(polys):
        poly_start.append(idx)
        m = len(poly)
        for i in range(m):
            u = idx + i
            v = idx + (i + 1) % m
            w = 0.0
            g[u].append((v, w))
            g[v].append((u, w))
        idx += m

    # Visibility edges between all pairs not passing through building interior
    for i in range(N):
        for j in range(i + 1, N):
            # perimeter neighbors already added, but general edge may also exist with same or bigger cost
            a, b = pts[i], pts[j]
            blocked = False
            for poly in polys:
                # allow endpoints on boundary/vertices, but segment must not pass through interior
                nvert = len(poly)
                inter_cnt = 0
                for k in range(nvert):
                    c = poly[k]
                    d = poly[(k + 1) % nvert]
                    if seg_proper_intersect(a, b, c, d):
                        # if intersection only at shared endpoint, can be okay; handled below by midpoint test
                        pass
                # midpoint test on tiny perturbation is cumbersome; use interval sampling:
                # segment invalid if there exists an interior point inside polygon.
                mid = (a + b) * 0.5
                if point_in_convex(poly, mid):
                    # if whole segment lies on boundary edge, it's okay
                    on_some_edge = False
                    for k in range(nvert):
                        c = poly[k]
                        d = poly[(k + 1) % nvert]
                        if point_on_segment(a, c, d) and point_on_segment(b, c, d):
                            on_some_edge = True
                            break
                    if not on_some_edge:
                        blocked = True
                        break
                else:
                    # if intersects polygon away from endpoints, blocked
                    for k in range(nvert):
                        c = poly[k]
                        d = poly[(k + 1) % nvert]
                        if seg_proper_intersect(a, b, c, d):
                            # allow touching at endpoints only
                            ok = False
                            for p in (a, b):
                                if (abs(p.x - c.x) < EPS and abs(p.y - c.y) < EPS) or (abs(p.x - d.x) < EPS and abs(p.y - d.y) < EPS):
                                    ok = True
                            if not ok:
                                blocked = True
                                break
                    if blocked:
                        break
            if blocked:
                continue
            w = sunlight_cost(a, b, polys, sun)
            g[i].append((j, w))
            g[j].append((i, w))

    # Dijkstra
    dista = [INF] * N
    dista[0] = 0.0
    import heapq
    pq = [(0.0, 0)]
    while pq:
        cd, u = heapq.heappop(pq)
        if cd > dista[u] + 1e-12:
            continue
        if u == 1:
            break
        for v, w in g[u]:
            nd = cd + w
            if nd + 1e-12 < dista[v]:
                dista[v] = nd
                heapq.heappush(pq, (nd, v))

    print("{:.10f}".format(dista[1]))

