#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x, ld y) : x(x), y(y) {}
    Point operator+(const Point& p) const { return Point(x + p.x, y + p.y); }
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    Point operator*(ld s) const { return Point(x * s, y * s); }
    ld cross(const Point& p) const { return x * p.y - y * p.x; }
    ld dot(const Point& p) const { return x * p.x + y * p.y; }
    ld dist2() const { return x * x + y * y; }
    ld dist() const { return sqrtl(dist2()); }
};

struct Segment {
    Point a, b;
    Segment() {}
    Segment(Point a, Point b) : a(a), b(b) {}
};

// Returns true if p is on segment s
bool pointOnSegment(Point p, Segment s) {
    return fabs(s.a.cross(s.b - s.a) - p.cross(s.b - s.a)) < EPS &&
           min(s.a.x, s.b.x) - EPS <= p.x && p.x <= max(s.a.x, s.b.x) + EPS &&
           min(s.a.y, s.b.y) - EPS <= p.y && p.y <= max(s.a.y, s.b.y) + EPS;
}

// Returns true if segments s1 and s2 intersect
bool segmentsIntersect(Segment s1, Segment s2) {
    ld d1 = (s1.b - s1.a).cross(s2.a - s1.a);
    ld d2 = (s1.b - s1.a).cross(s2.b - s1.a);
    ld d3 = (s2.b - s2.a).cross(s1.a - s2.a);
    ld d4 = (s2.b - s2.a).cross(s1.b - s2.a);

    if (((d1 > EPS && d2 < -EPS) || (d1 < -EPS && d2 > EPS)) &&
        ((d3 > EPS && d4 < -EPS) || (d3 < -EPS && d4 > EPS)))
        return true;

    // Collinear cases
    if (fabs(d1) < EPS && pointOnSegment(s2.a, s1)) return true;
    if (fabs(d2) < EPS && pointOnSegment(s2.b, s1)) return true;
    if (fabs(d3) < EPS && pointOnSegment(s1.a, s2)) return true;
    if (fabs(d4) < EPS && pointOnSegment(s1.b, s2)) return true;

    return false;
}

// Returns true if point p is inside convex polygon poly
bool pointInsidePolygon(Point p, const vector<Point>& poly) {
    int n = poly.size();
    bool positive = false, negative = false;
    for (int i = 0; i < n; i++) {
        ld cross = (poly[(i+1)%n] - poly[i]).cross(p - poly[i]);
        if (cross > EPS) positive = true;
        if (cross < -EPS) negative = true;
        if (positive && negative) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int N;
    cin >> N;

    vector<vector<Point>> buildings(N);
    for (int i = 0; i < N; i++) {
        int M;
        cin >> M;
        buildings[i].resize(M);
        for (int j = 0; j < M; j++) {
            cin >> buildings[i][j].x >> buildings[i][j].y;
        }
    }

    Point S, T;
    cin >> S.x >> S.y >> T.x >> T.y;

    // Check if S or T are inside any building
    for (const auto& poly : buildings) {
        if (pointInsidePolygon(S, poly) || pointInsidePolygon(T, poly)) {
            cout << 0.0 << "\n";
            return 0;
        }
    }

    // Collect all important points
    vector<Point> points;
    points.push_back(S);
    points.push_back(T);

    for (const auto& poly : buildings) {
        for (const auto& p : poly) {
            points.push_back(p);
        }
    }

    int n = points.size();

    // Build graph - edge exists if we can walk directly without entering buildings
    // and distance is counted as sunlight distance
    vector<vector<pair<int, ld>>> adj(n);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            Segment seg(points[i], points[j]);

            // Check if this segment intersects any building
            bool intersects = false;
            bool onBoundary = false;

            for (const auto& poly : buildings) {
                int m = poly.size();
                for (int k = 0; k < m; k++) {
                    Segment edge(poly[k], poly[(k+1)%m]);

                    // Check if the segment is on the boundary
                    if (pointOnSegment(points[i], edge) && pointOnSegment(points[j], edge)) {
                        onBoundary = true;
                    }

                    if (segmentsIntersect(seg, edge)) {
                        // Check if intersection is at endpoints only
                        bool onlyAtEndpoints = true;
                        Point inter;
                        // Simplified - just check if it's not just touching at endpoints
                        if (!pointOnSegment(points[i], edge) && !pointOnSegment(points[j], edge)) {
                            intersects = true;
                            break;
                        }
                    }
                }
                if (intersects) break;
            }

            if (!intersects) {
                ld dist = (points[i] - points[j]).dist();
                adj[i].push_back({j, dist});
                adj[j].push_back({i, dist});
            }
        }
    }

    // Dijkstra
    vector<ld> dist(n, 1e18);
    vector<bool> visited(n, false);
    priority_queue<pair<ld, int>, vector<pair<ld, int>>, greater<pair<ld, int>>> pq;

    dist[0] = 0;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (visited[u]) continue;
        visited[u] = true;

        if (u == 1) break;

        for (auto [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    cout << dist[1] << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const double INF = 1e100;
static const double EPS = 1e-10;

struct Point {
    double x, y;
    Point() {}
    Point(double x_, double y_) : x(x_), y(y_) {}
    Point operator + (const Point& o) const { return Point(x + o.x, y + o.y); }
    Point operator - (const Point& o) const { return Point(x - o.x, y - o.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
    Point operator / (double k) const { return Point(x / k, y / k); }
};

double dot(const Point& a, const Point& b) { return a.x * b.x + a.y * b.y; }
double cross(const Point& a, const Point& b) { return a.x * b.y - a.y * b.x; }
double norm2(const Point& a) { return dot(a, a); }
double dist(const Point& a, const Point& b) { return sqrt(norm2(a - b)); }

int sgn(double x) {
    if (x > EPS) return 1;
    if (x < -EPS) return -1;
    return 0;
}

bool onSegment(const Point& a, const Point& b, const Point& p) {
    return sgn(cross(b - a, p - a)) == 0 && sgn(dot(p - a, p - b)) <= 0;
}

bool segmentsProperIntersect(const Point& a, const Point& b, const Point& c, const Point& d) {
    double c1 = cross(b - a, c - a);
    double c2 = cross(b - a, d - a);
    double c3 = cross(d - c, a - c);
    double c4 = cross(d - c, b - c);
    return sgn(c1) * sgn(c2) < 0 && sgn(c3) * sgn(c4) < 0;
}

bool segmentsIntersect(const Point& a, const Point& b, const Point& c, const Point& d) {
    if (segmentsProperIntersect(a, b, c, d)) return true;
    if (onSegment(a, b, c)) return true;
    if (onSegment(a, b, d)) return true;
    if (onSegment(c, d, a)) return true;
    if (onSegment(c, d, b)) return true;
    return false;
}

double pointSegmentDistance(const Point& p, const Point& a, const Point& b) {
    Point ab = b - a;
    double t = dot(p - a, ab) / max(EPS, norm2(ab));
    t = max(0.0, min(1.0, t));
    Point q = a + ab * t;
    return dist(p, q);
}

struct Polygon {
    vector<Point> p;
};

bool pointInConvexOrBoundary(const Polygon& poly, const Point& q) {
    int n = (int)poly.p.size();
    int sign = 0;
    for (int i = 0; i < n; ++i) {
        Point a = poly.p[i], b = poly.p[(i + 1) % n];
        double cr = cross(b - a, q - a);
        int s = sgn(cr);
        if (s == 0 && onSegment(a, b, q)) return true;
        if (s != 0) {
            if (sign == 0) sign = s;
            else if (sign != s) return false;
        }
    }
    return true;
}

bool pointStrictlyInsideConvex(const Polygon& poly, const Point& q) {
    int n = (int)poly.p.size();
    int sign = 0;
    for (int i = 0; i < n; ++i) {
        Point a = poly.p[i], b = poly.p[(i + 1) % n];
        double cr = cross(b - a, q - a);
        int s = sgn(cr);
        if (s == 0) return false;
        if (sign == 0) sign = s;
        else if (sign != s) return false;
    }
    return true;
}

bool segmentPassesBuildingInterior(const Polygon& poly, const Point& a, const Point& b) {
    // If either endpoint strictly inside, invalid.
    if (pointStrictlyInsideConvex(poly, a) || pointStrictlyInsideConvex(poly, b)) return true;

    // If segment properly intersects any edge, then it enters interior.
    int n = (int)poly.p.size();
    for (int i = 0; i < n; ++i) {
        Point c = poly.p[i], d = poly.p[(i + 1) % n];
        if (segmentsProperIntersect(a, b, c, d)) return true;
    }

    // Midpoint test for collinear/boundary-touch weird cases.
    Point mid = (a + b) * 0.5;
    if (pointStrictlyInsideConvex(poly, mid)) return true;

    return false;
}

// Sun direction vector D: rays go in direction D from sun to ground.
// A point q is shadowed by polygon if ray q - t*D (t>=0) hits polygon.
// Equivalent: q lies in polygon + nonnegative span of D.
bool pointInShadowOfPolygon(const Polygon& poly, const Point& q, const Point& D) {
    if (pointInConvexOrBoundary(poly, q)) return true;

    int n = (int)poly.p.size();

    // If q lies on extension from any edge parallel to D? General intersection with ray.
    // Check if ray from q backwards along D intersects polygon.
    Point farPt = q - D * 1e9; // sufficiently far for coordinate ranges typical in ICPC
    for (int i = 0; i < n; ++i) {
        Point a = poly.p[i], b = poly.p[(i + 1) % n];
        if (segmentsIntersect(q, farPt, a, b)) return true;
    }
    return false;
}

// Shadow intervals on segment A->B.
vector<pair<double,double>> shadowIntervalsOnSegment(const Point& A, const Point& B,
                                                     const vector<Polygon>& polys,
                                                     const Point& D) {
    vector<double> ts = {0.0, 1.0};

    Point V = B - A;
    int m = polys.size();

    for (int idx = 0; idx < m; ++idx) {
        const auto& poly = polys[idx];
        int n = poly.p.size();

        // Add t where A+tV lies on polygon boundary
        for (int i = 0; i < n; ++i) {
            Point P = poly.p[i], Q = poly.p[(i + 1) % n];
            Point E = Q - P;

            double den = cross(V, E);
            if (fabs(den) > EPS) {
                double t = cross(P - A, E) / den;
                double u = cross(P - A, V) / den;
                if (t > EPS && t < 1.0 - EPS && u > -EPS && u < 1.0 + EPS) ts.push_back(t);
            } else {
                // Parallel: if collinear, add projections of endpoints
                if (fabs(cross(P - A, V)) < EPS) {
                    double vv = norm2(V);
                    if (vv > EPS) {
                        double t1 = dot(P - A, V) / vv;
                        double t2 = dot(Q - A, V) / vv;
                        if (t1 > EPS && t1 < 1.0 - EPS) ts.push_back(t1);
                        if (t2 > EPS && t2 < 1.0 - EPS) ts.push_back(t2);
                    }
                }
            }
        }

        // Add t where point is on shadow boundary ray from a vertex in direction D
        for (int i = 0; i < n; ++i) {
            Point P = poly.p[i];
            double den = cross(V, D);
            if (fabs(den) > EPS) {
                double t = cross(P - A, D) / den;
                double s = cross(P - A, V) / den;
                if (t > EPS && t < 1.0 - EPS && s > -EPS) ts.push_back(t);
            } else {
                // Segment parallel to shadow rays; ignore, midpoint classification handles it.
            }
        }
    }

    sort(ts.begin(), ts.end());
    vector<double> uniq;
    for (double x : ts) {
        if (uniq.empty() || fabs(x - uniq.back()) > 1e-9) uniq.push_back(x);
    }
    ts.swap(uniq);

    vector<pair<double,double>> shaded;
    for (int i = 0; i + 1 < (int)ts.size(); ++i) {
        double l = ts[i], r = ts[i+1];
        if (r - l < 1e-12) continue;
        double mid = (l + r) * 0.5;
        Point M = A + V * mid;
        bool inShadow = false;
        for (const auto& poly : polys) {
            if (pointInShadowOfPolygon(poly, M, D)) {
                inShadow = true;
                break;
            }
        }
        if (inShadow) shaded.push_back({l, r});
    }

    // Merge
    if (shaded.empty()) return shaded;
    vector<pair<double,double>> merged;
    merged.push_back(shaded[0]);
    for (int i = 1; i < (int)shaded.size(); ++i) {
        if (shaded[i].first <= merged.back().second + 1e-9)
            merged.back().second = max(merged.back().second, shaded[i].second);
        else
            merged.push_back(shaded[i]);
    }
    return merged;
}

double sunlightCost(const Point& A, const Point& B, const vector<Polygon>& polys, const Point& D) {
    double L = dist(A, B);
    if (L < EPS) return 0.0;

    // Movement along building perimeter is shaded, but our graph edges that lie on perimeter
    // are between vertices of the same polygon boundary and will be handled by caller as zero.
    // For general visible segment, sunlight = length outside all shadows.
    auto intervals = shadowIntervalsOnSegment(A, B, polys, D);
    double shadedFrac = 0.0;
    for (auto &pr : intervals) shadedFrac += pr.second - pr.first;
    shadedFrac = min(1.0, max(0.0, shadedFrac));
    return L * (1.0 - shadedFrac);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    Point S, T, D;
    cin >> S.x >> S.y >> T.x >> T.y >> D.x >> D.y;

    vector<Polygon> polys(N);
    vector<Point> nodes;
    nodes.push_back(S);
    nodes.push_back(T);

    for (int i = 0; i < N; ++i) {
        int m;
        cin >> m;
        polys[i].p.resize(m);
        for (int j = 0; j < m; ++j) {
            cin >> polys[i].p[j].x >> polys[i].p[j].y;
            nodes.push_back(polys[i].p[j]);
        }
    }

    int Vn = nodes.size();
    vector<vector<pair<int,double>>> adj(Vn);

    auto addEdge = [&](int u, int v, double w) {
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    };

    // Zero-cost edges along polygon perimeters.
    int base = 2;
    for (int i = 0; i < N; ++i) {
        int m = polys[i].p.size();
        for (int j = 0; j < m; ++j) {
            int u = base + j;
            int v = base + (j + 1) % m;
            addEdge(u, v, 0.0);
        }
        base += m;
    }

    // Visibility edges between all node pairs not passing through building interiors.
    for (int i = 0; i < Vn; ++i) {
        for (int j = i + 1; j < Vn; ++j) {
            bool ok = true;
            for (const auto& poly : polys) {
                if (segmentPassesBuildingInterior(poly, nodes[i], nodes[j])) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;

            // If this is a polygon boundary edge, already added with zero cost.
            bool boundaryEdge = false;
            int cur = 2;
            for (int pi = 0; pi < N && !boundaryEdge; ++pi) {
                int m = polys[pi].p.size();
                for (int k = 0; k < m; ++k) {
                    int a = cur + k;
                    int b = cur + (k + 1) % m;
                    if ((a == i && b == j) || (a == j && b == i)) {
                        boundaryEdge = true;
                        break;
                    }
                }
                cur += m;
            }
            if (boundaryEdge) continue;

            double w = sunlightCost(nodes[i], nodes[j], polys, D);
            addEdge(i, j, w);
        }
    }

    // Dijkstra
    vector<double> d(Vn, INF);
    priority_queue<pair<double,int>, vector<pair<double,int>>, greater<pair<double,int>>> pq;
    d[0] = 0.0;
    pq.push({0.0, 0});
    while (!pq.empty()) {
        auto [cd, u] = pq.top();
        pq.pop();
        if (cd > d[u] + 1e-12) continue;
        if (u == 1) break;
        for (auto [v, w] : adj[u]) {
            if (d[v] > d[u] + w + 1e-12) {
                d[v] = d[u] + w;
                pq.push({d[v], v});
            }
        }
    }

    cout << fixed << setprecision(10) << d[1] << "\n";
    return 0;
}

