    static final double EPS = 1e-9;

    // 2D point class
    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
        Point sub(Point p) { return new Point(x - p.x, y - p.y); }
        double dot(Point p) { return x * p.x + y * p.y; }
        double cross(Point p) { return x * p.y - y * p.x; }
        double norm2() { return x*x + y*y; }
        double dist(Point p) { return Math.sqrt(sub(p).norm2()); }
    }

    // Check if point q lies on segment pr (including endpoints)
    static boolean onSegment(Point p, Point q, Point r) {
        if (Math.abs(q.sub(p).cross(r.sub(p))) > EPS) return false;
        double dot = q.sub(p).dot(r.sub(p));
        double norm2 = r.sub(p).norm2();
        return dot >= -EPS && dot <= norm2 + EPS;
    }

    // Check if two segments AB and CD intersect (including endpoints)
    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double o1 = a.sub(b).cross(c.sub(b));
        double o2 = a.sub(b).cross(d.sub(b));
        double o3 = c.sub(d).cross(a.sub(d));
        double o4 = c.sub(d).cross(b.sub(d));
        if (o1 * o2 < -EPS || o3 * o4 < -EPS) return false;
        if (Math.abs(o1) < EPS && Math.abs(o2) < EPS) {
            // collinear - check overlap
            return onSegment(a, c, b) || onSegment(a, d, b) ||
                   onSegment(c, a, d) || onSegment(c, b, d);
        }
        return true;
    }

    // Check if point p is inside convex polygon (vertices in CCW order, no 3 collinear)
    static boolean pointInConvexPolygon(Point p, List<Point> poly) {
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i+1)%n);
            if (b.sub(a).cross(p.sub(a)) < -EPS) return false;
        }
        return true;
    }

    // Check if point p is strictly inside polygon (not on boundary)
    static boolean pointStrictlyInside(Point p, List<Point> poly) {
        int n = poly.size();
        for (int i = 0; i < n; i++) {
            Point a = poly.get(i);
            Point b = poly.get((i+1)%n);
            if (b.sub(a).cross(p.sub(a)) < EPS) return false;
        }
        return true;
    }

