import java.io.*;
import java.util.*;

/*
ICPC - Industrial Convex Pillar City

Idea:
Rotate coordinates so sunlight direction becomes vertical downward.
Then shadows of buildings are vertical projections of buildings downward.
Walking in shade means:
- on any building boundary
- inside any shadow region

In rotated coordinates (u,v):
- sunlight exposure only depends on horizontal movement while outside shadow.
- Vertical movement costs 0 if done at fixed u.
So shortest sunlight distance is the minimum total length of horizontal movement
needed to go from x=uS to x=uT while staying in the union of "free horizontal levels".

For a fixed horizontal strip between consecutive critical y-values, the set of x covered
by shadows/building projections is constant and equals union of x-intervals of buildings
whose top is above the strip and bottom is below/at top of strip. Since buildings are convex,
intersection with a horizontal line is an interval, and shadow extends vertically downward
with same x-range as the whole polygon projection, i.e. [minX(poly), maxX(poly)].

We build a graph on interval endpoints at each critical y-level:
critical levels = y(S), y(T), and all polygon vertex y's.
At each level, compute covered x-interval union. Complement gives sunlit intervals.
A state is a point (level, x endpoint or S/T x if on that level) that lies in sunlit region
or on its boundary. Vertical edges of cost 0 connect same x across adjacent levels if that x
remains sunlit through the strip. Horizontal edges on same level connect consecutive states
with cost difference in x, but only through sunlit portions; equivalently connect neighboring
sorted allowed points within each sunlit interval.

Also if S or T are inside covered region at their level, they are already in shade; still they
are valid states. Horizontal movement starting from inside covered region is impossible at that
level unless reaching boundary through covered region, which costs 0 because covered means shade.
Thus on each level, movement cost between two x's equals sunlit length along segment between them,
i.e. segment length minus covered length. Since covered union known, we can connect all points on
same level by shortest 1D weighted metric via consecutive sorted points with edge weight equal
sunlit measure between them.

Then run Dijkstra.

Complexities okay for moderate N total vertices.
*/

public class Main {
    static final double EPS = 1e-9;
    static final double INF = 1e100;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 1;
                c = read();
                while (c > ' ' && c != -1) {
                    mul *= 0.1;
                    val += (c - '0') * mul;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    static class Pt {
        double x, y;
        Pt(double x, double y) { this.x = x; this.y = y; }
    }

    static class Building {
        int m;
        Pt[] p;
        double minX, maxX, minY, maxY;
    }

    static class Interval {
        double l, r;
        Interval(double l, double r) { this.l = l; this.r = r; }
    }

    static class Edge {
        int to;
        double w;
        Edge(int to, double w) { this.to = to; this.w = w; }
    }

    static int n;
    static double sx, sy, tx, ty;
    static double sunx, suny;
    static Building[] buildings;

    static double[] levels;
    static ArrayList<Interval>[] coveredAtLevel;
    static ArrayList<Double>[] xsAtLevel;
    static ArrayList<Integer>[] nodeIdsAtLevel;
    static ArrayList<Edge>[] graph;
    static ArrayList<Double> nodeX = new ArrayList<>();
    static ArrayList<Integer> nodeLevel = new ArrayList<>();

    static int addNode(int level, double x) {
        int id = nodeX.size();
        nodeX.add(x);
        nodeLevel.add(level);
        return id;
    }

    static boolean inCovered(ArrayList<Interval> cov, double x) {
        int lo = 0, hi = cov.size() - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            Interval in = cov.get(mid);
            if (x < in.l - EPS) hi = mid - 1;
            else if (x > in.r + EPS) lo = mid + 1;
            else return true;
        }
        return false;
    }

    static double coveredLengthBetween(ArrayList<Interval> cov, double a, double b) {
        if (a > b) { double t = a; a = b; b = t; }
        double res = 0;
        for (Interval in : cov) {
            double l = Math.max(a, in.l);
            double r = Math.min(b, in.r);
            if (r > l + EPS) res += r - l;
        }
        return res;
    }

    static ArrayList<Interval> mergeIntervals(ArrayList<Interval> arr) {
        arr.sort(Comparator.comparingDouble(o -> o.l));
        ArrayList<Interval> res = new ArrayList<>();
        for (Interval it : arr) {
            if (it.r < it.l + EPS) continue;
            if (res.isEmpty() || it.l > res.get(res.size() - 1).r + EPS) {
                res.add(new Interval(it.l, it.r));
            } else {
                res.get(res.size() - 1).r = Math.max(res.get(res.size() - 1).r, it.r);
            }
        }
        return res;
    }

    static void addUndirected(int u, int v, double w) {
        graph[u].add(new Edge(v, w));
        graph[v].add(new Edge(u, w));
    }

    static class NodeDist implements Comparable<NodeDist> {
        int v;
        double d;
        NodeDist(int v, double d) { this.v = v; this.d = d; }
        public int compareTo(NodeDist o) { return Double.compare(d, o.d); }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        n = fs.nextInt();
        sx = fs.nextDouble();
        sy = fs.nextDouble();
        tx = fs.nextDouble();
        ty = fs.nextDouble();
        sunx = fs.nextDouble();
        suny = fs.nextDouble();

        buildings = new Building[n];

        // Rotate coordinates so sun direction becomes (0,-1)
        // Let e1 = perpendicular to sun = (-suny, sunx), e2 = sun direction = (sunx, suny)
        // Then use u = dot(p,e1), v = dot(p,e2). Shadow extends toward decreasing v.
        double len = Math.hypot(sunx, suny);
        sunx /= len;
        suny /= len;
        double ex = -suny, ey = sunx; // horizontal axis

        Pt S = rot(sx, sy, ex, ey, sunx, suny);
        Pt T = rot(tx, ty, ex, ey, sunx, suny);

        ArrayList<Double> lvlList = new ArrayList<>();
        lvlList.add(S.y);
        lvlList.add(T.y);

        for (int i = 0; i < n; i++) {
            int m = fs.nextInt();
            Building b = new Building();
            b.m = m;
            b.p = new Pt[m];
            b.minX = INF; b.maxX = -INF; b.minY = INF; b.maxY = -INF;
            for (int j = 0; j < m; j++) {
                double x = fs.nextDouble(), y = fs.nextDouble();
                Pt q = rot(x, y, ex, ey, sunx, suny);
                b.p[j] = q;
                b.minX = Math.min(b.minX, q.x);
                b.maxX = Math.max(b.maxX, q.x);
                b.minY = Math.min(b.minY, q.y);
                b.maxY = Math.max(b.maxY, q.y);
                lvlList.add(q.y);
            }
            buildings[i] = b;
        }

        levels = uniqueSorted(lvlList);
        int L = levels.length;

        coveredAtLevel = new ArrayList[L];
        xsAtLevel = new ArrayList[L];
        nodeIdsAtLevel = new ArrayList[L];
        for (int i = 0; i < L; i++) {
            coveredAtLevel[i] = new ArrayList<>();
            xsAtLevel[i] = new ArrayList<>();
            nodeIdsAtLevel[i] = new ArrayList<>();
        }

        for (int i = 0; i < L; i++) {
            double y = levels[i];
            ArrayList<Interval> cov = new ArrayList<>();
            for (Building b : buildings) {
                if (b.maxY + EPS >= y) {
                    cov.add(new Interval(b.minX, b.maxX));
                }
            }
            coveredAtLevel[i] = mergeIntervals(cov);
        }

        int sLevel = findLevel(S.y);
        int tLevel = findLevel(T.y);

        xsAtLevel[sLevel].add(S.x);
        xsAtLevel[tLevel].add(T.x);

        for (int i = 0; i < L; i++) {
            for (Interval in : coveredAtLevel[i]) {
                xsAtLevel[i].add(in.l);
                xsAtLevel[i].add(in.r);
            }
        }

        for (int i = 0; i < L; i++) {
            ArrayList<Double> xs = xsAtLevel[i];
            xs.sort(Double::compare);
            ArrayList<Double> uniq = new ArrayList<>();
            for (double x : xs) {
                if (uniq.isEmpty() || Math.abs(x - uniq.get(uniq.size() - 1)) > EPS) uniq.add(x);
            }
            xsAtLevel[i] = uniq;
        }

        int totalNodes = 0;
        for (int i = 0; i < L; i++) {
            for (double x : xsAtLevel[i]) {
                int id = addNode(i, x);
                nodeIdsAtLevel[i].add(id);
                totalNodes++;
            }
        }

        graph = new ArrayList[totalNodes];
        for (int i = 0; i < totalNodes; i++) graph[i] = new ArrayList<>();

        int sId = -1, tId = -1;

        for (int i = 0; i < L; i++) {
            ArrayList<Double> xs = xsAtLevel[i];
            ArrayList<Integer> ids = nodeIdsAtLevel[i];
            for (int k = 0; k < xs.size(); k++) {
                double x = xs.get(k);
                int id = ids.get(k);
                if (i == sLevel && Math.abs(x - S.x) <= EPS) sId = id;
                if (i == tLevel && Math.abs(x - T.x) <= EPS) tId = id;
            }
            for (int k = 0; k + 1 < xs.size(); k++) {
                double a = xs.get(k), b = xs.get(k + 1);
                double covered = coveredLengthBetween(coveredAtLevel[i], a, b);
                double cost = Math.abs(b - a) - covered;
                if (cost < EPS) cost = 0;
                addUndirected(ids.get(k), ids.get(k + 1), cost);
            }
        }

        // Vertical zero-cost edges where same x can move through strip without entering building interior.
        // Since shadows are vertical and building boundaries are shaded, moving vertically at fixed x
        // is always allowed unless passing through strict interior of a building not on boundary.
        // For convex polygon, if x in (minX,maxX) and y within polygon vertical span, could intersect interior.
        // However any such x is covered (shadow), and optimal graph only needs boundary x-values / S/T.
        // Connect same x between adjacent levels when x is not strictly inside any building cross-section
        // throughout the open strip. We test at midpoint.
        for (int i = 0; i + 1 < L; i++) {
            HashMap<Long, Integer> map = new HashMap<>();
            for (int k = 0; k < xsAtLevel[i].size(); k++) {
                map.put(key(xsAtLevel[i].get(k)), nodeIdsAtLevel[i].get(k));
            }
            for (int k = 0; k < xsAtLevel[i + 1].size(); k++) {
                double x = xsAtLevel[i + 1].get(k);
                Integer u = map.get(key(x));
                if (u != null) {
                    if (verticalAllowed(x, levels[i], levels[i + 1])) {
                        int v = nodeIdsAtLevel[i + 1].get(k);
                        addUndirected(u, v, 0);
                    }
                }
            }
        }

        double ans = dijkstra(sId, tId);
        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static Pt rot(double x, double y, double ex, double ey, double sx, double sy) {
        return new Pt(x * ex + y * ey, x * sx + y * sy);
    }

    static double[] uniqueSorted(ArrayList<Double> arr) {
        Collections.sort(arr);
        ArrayList<Double> res = new ArrayList<>();
        for (double v : arr) {
            if (res.isEmpty() || Math.abs(v - res.get(res.size() - 1)) > EPS) res.add(v);
        }
        double[] out = new double[res.size()];
        for (int i = 0; i < res.size(); i++) out[i] = res.get(i);
        return out;
    }

    static int findLevel(double y) {
        for (int i = 0; i < levels.length; i++) {
            if (Math.abs(levels[i] - y) <= EPS) return i;
        }
        return -1;
    }

    static long key(double x) {
        return Math.round(x * 1e9);
    }

    static boolean verticalAllowed(double x, double y1, double y2) {
        double mid = (y1 + y2) * 0.5;
        for (Building b : buildings) {
            if (mid > b.maxY - EPS || mid < b.minY + EPS) continue;
            if (pointStrictlyInsidePolygon(x, mid, b.p)) return false;
        }
        return true;
    }

    static boolean pointStrictlyInsidePolygon(double x, double y, Pt[] p) {
        int n = p.length;
        double prev = 0;
        for (int i = 0; i < n; i++) {
            Pt a = p[i], b = p[(i + 1) % n];
            double cross = (b.x - a.x) * (y - a.y) - (b.y - a.y) * (x - a.x);
            if (Math.abs(cross) <= EPS) continue;
            if (prev == 0) prev = cross;
            else if (cross * prev < -EPS) return false;
        }
        // inside or boundary for convex polygon, now exclude boundary
        for (int i = 0; i < n; i++) {
            Pt a = p[i], b = p[(i + 1) % n];
            double cross = (b.x - a.x) * (y - a.y) - (b.y - a.y) * (x - a.x);
            if (Math.abs(cross) <= EPS) {
                double dot = (x - a.x) * (x - b.x) + (y - a.y) * (y - b.y);
                if (dot <= EPS) return false;
            }
        }
        return true;
    }

    static double dijkstra(int s, int t) {
        double[] dist = new double[graph.length];
        Arrays.fill(dist, INF);
        PriorityQueue<NodeDist> pq = new PriorityQueue<>();
        dist[s] = 0;
        pq.add(new NodeDist(s, 0));
        while (!pq.isEmpty()) {
            NodeDist cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            if (cur.v == t) return cur.d;
            for (Edge e : graph[cur.v]) {
                double nd = cur.d + e.w;
                if (nd + EPS < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new NodeDist(e.to, nd));
                }
            }
        }
        return dist[t];
    }
}
